# November 19, 2026: the Crowsnest Pass coal towns (Coleman, Blairmore, Frank, Hillcrest, Bellevue, Passburg, Lille) and
# Fort Macleod and Lundbreck to the east, Alberta. Region ab drawn at random by tools/choose.py --claim. Sources opened in
# this session: the Canadian Register of Historic Places statement for each designated place (historicplaces.ca, read
# with tools/page.py --all); Wikipedia as raw text (tools/wiki_raw.py); the operators' own pages (Leitch Collieries and
# Frank Slide Interpretive Centre, both Government of Alberta sites; the Bellevue Underground Mine; the Crowsnest Museum;
# the Town of Fort Macleod); the Alberta heritage blog RETROactive on the Bellevue mine; the Crowsnest Pass "Take a Hike"
# trail sheet and the Friends of the Frank Slide Centre's Lille hike; Waymarking pages that quote interpretive signs
# (Coleman coke ovens, Lime City kilns) and give their positions; CBC and Lethbridge News Now on the Fort Macleod court
# house sale.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def HP(t,i): return ['Canadian Register of Historic Places: '+t,'https://www.historicplaces.ca/en/rep-reg/place-lieu.aspx?id=%d'%i]
BATCH={'key':'ab_pfsz','label':'Crowsnest Pass and Fort Macleod, Alberta','added':'2026-11-19 04:32'}
LEITCH=L('Leitch Collieries: plan your visit','https://leitchcollieries.ca/plan-your-visit')
